"""A2A server errors outside the a2a-sdk type union."""

from __future__ import annotations


class A2AMessageInFlightConflict(Exception):
    """Duplicate ``messageId`` received while the first request is still processing."""

    def __init__(self, *, context_id: str, message_id: str) -> None:
        self.context_id = context_id
        self.message_id = message_id
        super().__init__(
            f"message_id {message_id!r} is already in flight for context {context_id!r}"
        )


class A2APushNotificationUrlRejected(Exception):
    """Push callback URL failed SSRF policy checks."""

    def __init__(self, message: str) -> None:
        self.message = message
        super().__init__(message)
